package dev.phonepad;

import android.content.Context;
import android.graphics.*;
import android.graphics.drawable.Drawable;
import android.view.View;
import java.util.*;

/** The same keycaps, mouse regions and controller glyphs in inspectors and sequences. */
final class InputTokens extends View {
    private final List<String> tokens;private final Paint paint=new Paint(3);
    InputTokens(Context context,String expression){super(context);tokens=Arrays.asList(expression.split("\\+"));setContentDescription(expression);setMinimumHeight(EditorStyle.dp(context,42));}
    static InputTokens sequence(Context context,String program){StringJoiner result=new StringJoiner("+");int count=0;for(String line:program.split("\n")){String[] parts=line.trim().split("\\s+",2);if(parts.length<2||parts[0].startsWith("#"))continue;if(count++>=4){result.add("…");break;}if(count>1)result.add("→");if(parts[0].equals("press"))result.add(parts[1]);else if(parts[0].equals("release")){result.add("↑");result.add(parts[1]);}else result.add(parts[0].equals("wait")?parts[1]+" ms":parts[0]+" "+parts[1]);}return new InputTokens(context,result.toString());}
    @Override protected void onMeasure(int width,int height){int w=MeasureSpec.getSize(width);if(w==0)w=EditorStyle.dp(getContext(),180);setMeasuredDimension(w,resolveSize(EditorStyle.dp(getContext(),48),height));}
    @Override protected void onDraw(Canvas canvas){float density=getResources().getDisplayMetrics().density,x=4*density,h=Math.min(getHeight()-8*density,36*density);for(String token:tokens){if(token.isEmpty())continue;String label=DeviceDiagram.shortName(token);paint.setTextSize(12*density);float w=Math.max(34*density,paint.measureText(label)+18*density);if(x+w>getWidth()){paint.setColor(EditorStyle.MUTED);canvas.drawText("…",Math.max(0,getWidth()-14*density),getHeight()/2f+4*density,paint);break;}drawToken(canvas,paint,token,new RectF(x,(getHeight()-h)/2,x+w,(getHeight()+h)/2),density);x+=w+5*density;}}
    static void drawToken(Canvas canvas,Paint p,String token,RectF r,float density){String clean=token.replace("PAD_","");boolean face=clean.matches("[ABXY]");p.setStyle(Paint.Style.FILL);p.setColor(EditorStyle.SURFACE);if(face)canvas.drawOval(r,p);else canvas.drawRoundRect(r,5*density,5*density,p);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(density);p.setColor(face?ControllerSymbols.faceColor(clean,false,false):EditorStyle.LINE);if(face)canvas.drawOval(r,p);else canvas.drawRoundRect(r,5*density,5*density,p);p.setStyle(Paint.Style.FILL);p.setColor(face?ControllerSymbols.faceColor(clean,false,false):EditorStyle.TEXT);p.setTextAlign(Paint.Align.CENTER);p.setTextSize(12*density);String label=DeviceDiagram.shortName(token);canvas.drawText(label,r.centerX(),r.centerY()-(p.ascent()+p.descent())/2,p);}
    static Drawable icon(Context context,String token){return new Drawable(){final Paint p=new Paint(3);final int size=EditorStyle.dp(context,30);public int getIntrinsicWidth(){return size;}public int getIntrinsicHeight(){return size;}public void setAlpha(int alpha){p.setAlpha(alpha);}public void setColorFilter(ColorFilter filter){p.setColorFilter(filter);}public int getOpacity(){return PixelFormat.TRANSLUCENT;}public void draw(Canvas c){Rect b=getBounds();float u=b.width()/30f,x=b.exactCenterX(),y=b.exactCenterY();p.setColor(EditorStyle.TEAL);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(1.5f*u);if(token.contains("MOUSE")||token.contains("WHEEL")){c.drawRoundRect(x-8*u,y-12*u,x+8*u,y+12*u,7*u,7*u,p);c.drawLine(x,y-11*u,x,y-2*u,p);c.drawLine(x-7*u,y-2*u,x+7*u,y-2*u,p);}else if(token.startsWith("KEY_")){c.drawRoundRect(x-11*u,y-10*u,x+11*u,y+10*u,3*u,3*u,p);}else{c.drawCircle(x,y,11*u,p);if(token.startsWith("LS")||token.startsWith("RS")){c.drawCircle(x,y,5*u,p);return;}}p.setStyle(Paint.Style.FILL);p.setTextAlign(Paint.Align.CENTER);p.setTextSize(12*u);String label=token.startsWith("KEY_")?DeviceDiagram.shortName(token):token.replace("PAD_","");if(label.length()<=3)c.drawText(label,x,y+4*u,p);}};}
}
